{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        if n['parent'] is not None:
            children[n['parent']].append(n['id'])
    root_id = next(n['id'] for n in nodes if n['parent'] is None)
    all_symbols = set(n['symbol'] for n in nodes)
    for s in required_symbols:
        if s not in all_symbols:
            raise ValueError(f"Required symbol '{s}' not present")
    retained = set(node_by_id.keys())
    removed_list = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        has_retained_children = any(child in retained for child in children.get(nid, []))
        if has_retained_children:
            continue
        retained.remove(nid)
        removed_list.append(nid)
    retained_ids = sorted(retained)
    removed_ids = removed_list
    return {'removed_node_ids': removed_ids, 'retained_node_ids': retained_ids}"
}
